import torch
import torch.nn as nn

class BaselineGate(nn.Module):
    def __init__(self, model_dim, num_experts):
        super().__init__()
        self.fc = nn.Linear(model_dim, num_experts, bias=False)
        nn.init.normal_(self.fc.weight, std=0.02)

    def forward(self, x):
        return self.fc(x)
